// seed.js
// file to initialize database tasks.db (generated by Claude because original tasks.db was not given)
// run node seed.js (tasks.db will show up in the task-manager directory)

import Database from "better-sqlite3";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

// Put tasks.db where the starter template expects it: ../task-manager/tasks.db
const here = path.dirname(fileURLToPath(import.meta.url));
const dbDir = path.resolve(here, "../task-manager");
fs.mkdirSync(dbDir, { recursive: true });
const db = new Database(path.join(dbDir, "tasks.db"));

db.exec(`
  DROP TABLE IF EXISTS tasks;
  CREATE TABLE tasks (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    title       TEXT NOT NULL,
    assigned_to TEXT,
    due_date    TEXT,              -- ISO format: YYYY-MM-DD
    status      TEXT NOT NULL DEFAULT 'open'
                CHECK (status IN ('open', 'in_progress', 'completed'))
  );
`);

const insert = db.prepare(
  "INSERT INTO tasks (title, assigned_to, due_date, status) VALUES (?, ?, ?, ?)"
);

const tasks = [
  ["Set up project repo",      "Alice", "2025-03-28", "completed"],
  ["Design database schema",   "Bob",   "2025-04-01", "completed"],
  ["Write unit tests",         "Alice", "2025-04-10", "open"],
  ["Create login page",        "Carol", "2025-04-05", "in_progress"],
  ["Add task filtering",       "Bob",   "2025-04-12", "in_progress"],
  ["Write API documentation",  "Carol", "2025-04-20", "open"],
  ["Fix login bug",            "Bob",   "2025-04-15", "open"],
  ["Configure CI pipeline",    "Alice", "2025-04-08", "completed"],
  ["Add due-date reminders",   "Carol", "2025-04-25", "open"],
  ["Refactor task model",      "Bob",   "2025-04-18", "in_progress"],
  ["Accessibility review",     "Alice", "2025-04-22", "open"],
  ["Deploy to staging",        "Alice", "2025-04-30", "open"],
];

const insertAll = db.transaction((rows) => rows.forEach((r) => insert.run(...r)));
insertAll(tasks);

console.log(db.prepare("SELECT status, COUNT(*) AS n FROM tasks GROUP BY status").all());
db.close();